#include "all_fractal_definitions.h"

class cFractalTestv2pk : public cAbstractFractal
{
public:
	cFractalTestv2pk();
	void FormulaCode(CVector4 &z, const sFractal *fractal, sExtendedAux &aux) override;
};

cFractalTestv2pk::cFractalTestv2pk() : cAbstractFractal()
{
	nameInComboBox = "Test V2 PseudoKleinian";
	internalName = "test_v2_pk";
	internalID = fractal::testV2Pk;
	DEType = analyticDEType;
	DEFunctionType = logarithmicDEFunction;
	cpixelAddition = cpixelEnabledByDefault;
	defaultBailout = 2.5;
	DEAnalyticFunction = analyticFunctionLogarithmic;
	coloringFunction = coloringFunctionDefault;
}

void cFractalTestv2pk::FormulaCode(
	CVector4 &z, const sFractal *fractal, sExtendedAux &aux)
{
	// Combined formula - Sequential execution

	// ========== Stage 1: Riemann - Sphere Hobold Pow8 ==========
	{

			z *= fractal->transformCommon.scale08
					 / aux.r; // normalize vector to unit length => project onto sphere

			// find X-related iso-plane: polar projection onto unit circle
			double Kx_s0 = 2.0 * z.x * (1.0 - z.y) / ((z.y - 2.0) * z.y + z.x * z.x + 1.0);
			double Ky_s0 = 1.0 - 2.0 * ((z.y - 2.0) * z.y + 1.0) / ((z.y - 2.0) * z.y + z.x * z.x + 1.0);

			// doubled point
			double K2x_s0 = -2.0 * Kx_s0 * Ky_s0;
			double K2y_s0 = -(Ky_s0 * Ky_s0 - Kx_s0 * Kx_s0);

			// two more doublings (for total power eight)
			Kx_s0 = -2.0 * K2x_s0 * K2y_s0;
			Ky_s0 = -(K2y_s0 * K2y_s0 - K2x_s0 * K2x_s0);
			K2x_s0 = -2.0 * Kx_s0 * Ky_s0;
			K2y_s0 = -(Ky_s0 * Ky_s0 - Kx_s0 * Kx_s0);

			// (relevant) normal vector coordinates of doubled point plane
			double n1x_s0 = K2y_s0 - 1.0;
			double n1y_s0 = -K2x_s0;

			n1x_s0 += fractal->transformCommon.offsetA0; // offset tweak

			// find Z-related iso-plane: polar projection onto unit circle
			double Kz_s0 = 2.0 * z.z * (1.0 - z.y) / ((z.y - 2.0) * z.y + z.z * z.z + 1.0);
			Ky_s0 = 1.0 - 2.0 * ((z.y - 2.0) * z.y + 1.0) / ((z.y - 2.0) * z.y + z.z * z.z + 1.0);

			// doubled point
			double K2z_s0 = -2.0 * Kz_s0 * Ky_s0;
			K2y_s0 = -(Ky_s0 * Ky_s0 - Kz_s0 * Kz_s0);

			// two more doublings (for total power eight)
			Kz_s0 = -2.0 * K2z_s0 * K2y_s0;
			Ky_s0 = -(K2y_s0 * K2y_s0 - K2z_s0 * K2z_s0);
			K2z_s0 = -2.0 * Kz_s0 * Ky_s0;
			K2y_s0 = -(Ky_s0 * Ky_s0 - Kz_s0 * Kz_s0);

			// (relevant) normal vector coordinates of doubled point plane
			double n2y_s0 = -K2z_s0;
			double n2z_s0 = K2y_s0 - 1.0;

			n2z_s0 += fractal->transformCommon.offsetB0; // offset tweak

			// internal rotation
			if (fractal->transformCommon.angle0 != 0)
			{
				double tpx_s0 = n1x_s0;
				double tpz_s0 = n2z_s0;
				double beta_s0 = fractal->transformCommon.angle0 * M_PI_180;
				n1x_s0 = tpx_s0 * cos(beta_s0) + tpz_s0 * sin(beta_s0);
				n2z_s0 = tpx_s0 * -sin(beta_s0) + tpz_s0 * cos(beta_s0);
			}

			// compute position of doubled point as intersection of planes and sphere
			// solved ray parameter
			double nt_s0 =
				2.0 * (n1x_s0 * n1x_s0 * n2z_s0 * n2z_s0) / ((n1x_s0 * n1x_s0 + n1y_s0 * n1y_s0) * n2z_s0 * n2z_s0 + n1x_s0 * n1x_s0 * n2y_s0 * n2y_s0);

			// doubled point position
			z.y = 1.0 - nt_s0;
			z.x = n1y_s0 * (1.0 - z.y) / n1x_s0;
			z.z = n2y_s0 * (1.0 - z.y) / n2z_s0;

			// raise original length to the power, then add constant
			z *= aux.r * aux.r * aux.r * aux.r; // for 8th power

			z += fractal->transformCommon.additionConstant000;

			if (fractal->transformCommon.rotationEnabled)
				z = fractal->transformCommon.rotationMatrix.RotateVector(z);
			if (fractal->analyticDE.enabled)
			{
				aux.DE = fractal->analyticDE.offset1 + aux.DE * fabs(fractal->transformCommon.scale08) / aux.r;
				aux.DE *= 8.0 * fractal->analyticDE.scale1 * z.Length() / aux.r;
			}	}

	// ========== Stage 2: Riemann - Sphere Hobold Pow8 ==========
	{

			z *= fractal->transformCommon.scale08
					 / aux.r; // normalize vector to unit length => project onto sphere

			// find X-related iso-plane: polar projection onto unit circle
			double Kx_s1 = 2.0 * z.x * (1.0 - z.y) / ((z.y - 2.0) * z.y + z.x * z.x + 1.0);
			double Ky_s1 = 1.0 - 2.0 * ((z.y - 2.0) * z.y + 1.0) / ((z.y - 2.0) * z.y + z.x * z.x + 1.0);

			// doubled point
			double K2x_s1 = -2.0 * Kx_s1 * Ky_s1;
			double K2y_s1 = -(Ky_s1 * Ky_s1 - Kx_s1 * Kx_s1);

			// two more doublings (for total power eight)
			Kx_s1 = -2.0 * K2x_s1 * K2y_s1;
			Ky_s1 = -(K2y_s1 * K2y_s1 - K2x_s1 * K2x_s1);
			K2x_s1 = -2.0 * Kx_s1 * Ky_s1;
			K2y_s1 = -(Ky_s1 * Ky_s1 - Kx_s1 * Kx_s1);

			// (relevant) normal vector coordinates of doubled point plane
			double n1x_s1 = K2y_s1 - 1.0;
			double n1y_s1 = -K2x_s1;

			n1x_s1 += fractal->transformCommon.offsetA0; // offset tweak

			// find Z-related iso-plane: polar projection onto unit circle
			double Kz_s1 = 2.0 * z.z * (1.0 - z.y) / ((z.y - 2.0) * z.y + z.z * z.z + 1.0);
			Ky_s1 = 1.0 - 2.0 * ((z.y - 2.0) * z.y + 1.0) / ((z.y - 2.0) * z.y + z.z * z.z + 1.0);

			// doubled point
			double K2z_s1 = -2.0 * Kz_s1 * Ky_s1;
			K2y_s1 = -(Ky_s1 * Ky_s1 - Kz_s1 * Kz_s1);

			// two more doublings (for total power eight)
			Kz_s1 = -2.0 * K2z_s1 * K2y_s1;
			Ky_s1 = -(K2y_s1 * K2y_s1 - K2z_s1 * K2z_s1);
			K2z_s1 = -2.0 * Kz_s1 * Ky_s1;
			K2y_s1 = -(Ky_s1 * Ky_s1 - Kz_s1 * Kz_s1);

			// (relevant) normal vector coordinates of doubled point plane
			double n2y_s1 = -K2z_s1;
			double n2z_s1 = K2y_s1 - 1.0;

			n2z_s1 += fractal->transformCommon.offsetB0; // offset tweak

			// internal rotation
			if (fractal->transformCommon.angle0 != 0)
			{
				double tpx_s1 = n1x_s1;
				double tpz_s1 = n2z_s1;
				double beta_s1 = fractal->transformCommon.angle0 * M_PI_180;
				n1x_s1 = tpx_s1 * cos(beta_s1) + tpz_s1 * sin(beta_s1);
				n2z_s1 = tpx_s1 * -sin(beta_s1) + tpz_s1 * cos(beta_s1);
			}

			// compute position of doubled point as intersection of planes and sphere
			// solved ray parameter
			double nt_s1 =
				2.0 * (n1x_s1 * n1x_s1 * n2z_s1 * n2z_s1) / ((n1x_s1 * n1x_s1 + n1y_s1 * n1y_s1) * n2z_s1 * n2z_s1 + n1x_s1 * n1x_s1 * n2y_s1 * n2y_s1);

			// doubled point position
			z.y = 1.0 - nt_s1;
			z.x = n1y_s1 * (1.0 - z.y) / n1x_s1;
			z.z = n2y_s1 * (1.0 - z.y) / n2z_s1;

			// raise original length to the power, then add constant
			z *= aux.r * aux.r * aux.r * aux.r; // for 8th power

			z += fractal->transformCommon.additionConstant000;

			if (fractal->transformCommon.rotationEnabled)
				z = fractal->transformCommon.rotationMatrix.RotateVector(z);
			if (fractal->analyticDE.enabled)
			{
				aux.DE = fractal->analyticDE.offset1 + aux.DE * fabs(fractal->transformCommon.scale08) / aux.r;
				aux.DE *= 8.0 * fractal->analyticDE.scale1 * z.Length() / aux.r;
			}	}
}
